-	become_id(uid, gid);
-	/* end context switch */
+	/* Change uid, gid and supplementary group list. */
+	set_unix_security_ctx(uid, gid, ngroups, groups);

 	ctx_p->ut.ngroups = ngroups;

@@ -336,13 +346,11 @@

 	prev_ctx_p = &sec_ctx_stack[sec_ctx_stack_ndx];

-	/* Start context switch */
